input.sparql:
PREFIX brick: <https://brickschema.org/schema/brick#>
SELECT ?z ?label WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z rdfs:label ?label }
} LIMIT 50

PREFIX brick: <https://brickschema.org/schema/brick#>
SELECT ?s ?label WHERE {
  ?s a brick:ElectricPowerSensor .
  OPTIONAL { ?s rdfs:label ?label }
} LIMIT 50

SELECT ?type ?label WHERE {
  ?s a ?type .
  FILTER(strstarts(str(?type), "https://brickschema"))
  GROUP BY ?type ?label
} LIMIT 100

PREFIX brick: <https://brickschema.org/schema/brick#>
SELECT ?point ?label WHERE {
  ?point rdf:type/rdfs:label ?x .
} LIMIT 5

PREFIX brick: <https://brickschema.org/schema/brick#>
SELECT ?point WHERE {
  ?point a <https://brickschema.org/schema/Brick#ElectricPowerSensor> .
} LIMIT 20

PREFIX brick: <https://brickschema.org/schema/brick#>
SELECT ?point WHERE {
  ?point brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z01> .
  OPTIONAL { ?point rdfs:label ?label }
}
